--!strict
local Players=game:GetService("Players");local ReplicatedStorage=game:GetService("ReplicatedStorage");local player=Players.LocalPlayer;local remotes=ReplicatedStorage:WaitForChild("Remotes",10);if not remotes then return end;local catalogRemote=remotes:WaitForChild("ShopCatalogUpdated")::RemoteEvent;local request=remotes:WaitForChild("RequestShopCatalog")::RemoteEvent;local buy=remotes:WaitForChild("PurchaseWithCoins")::RemoteEvent;local equip=remotes:WaitForChild("EquipCosmetic")::RemoteEvent
local monetization=require(ReplicatedStorage.Modules.MonetizationConfig);local requestProduct=remotes:WaitForChild("RequestProductPurchase")::RemoteEvent;local requestPass=remotes:WaitForChild("RequestGamePassPurchase")::RemoteEvent
local gui=Instance.new("ScreenGui");gui.Name="ShopGui";gui.ResetOnSpawn=false;gui.Enabled=false;gui.Parent=player.PlayerGui;local frame=Instance.new("Frame");frame.Position=UDim2.fromScale(.15,.1);frame.Size=UDim2.fromScale(.7,.78);frame.BackgroundColor3=Color3.fromRGB(28,34,50);frame.Parent=gui;local title=Instance.new("TextLabel");title.Size=UDim2.fromScale(.8,.1);title.BackgroundTransparency=1;title.Text="爆笑村民商店";title.TextScaled=true;title.TextColor3=Color3.new(1,1,1);title.Parent=frame;local close=Instance.new("TextButton");close.Position=UDim2.fromScale(.88,.02);close.Size=UDim2.fromScale(.09,.07);close.Text="X";close.Parent=frame;close.Activated:Connect(function()gui.Enabled=false end);local scroll=Instance.new("ScrollingFrame");scroll.Position=UDim2.fromScale(.04,.12);scroll.Size=UDim2.fromScale(.92,.82);scroll.CanvasSize=UDim2.fromScale(0,2);scroll.BackgroundTransparency=1;scroll.Parent=frame;local layout=Instance.new("UIListLayout");layout.Padding=UDim.new(.01,0);layout.Parent=scroll
local function card(item:any)local f=Instance.new("Frame");f.Size=UDim2.fromScale(1,.1);f.BackgroundColor3=Color3.fromRGB(50,62,85);f.Parent=scroll;local text=Instance.new("TextLabel");text.Size=UDim2.fromScale(.72,1);text.BackgroundTransparency=1;text.Text=string.format("%s　%d Coins　[%s]\n%s",item.DisplayName,item.Price,item.Rarity,item.Description);text.TextWrapped=true;text.TextScaled=true;text.TextColor3=Color3.new(1,1,1);text.Parent=f;local b=Instance.new("TextButton");b.Position=UDim2.fromScale(.74,.15);b.Size=UDim2.fromScale(.23,.7);b.Text="購買 / 裝備";b.TextScaled=true;b.Parent=f;b.Activated:Connect(function()buy:FireServer(item.Id);task.delay(.3,function()equip:FireServer(item.Id)end)end)end
catalogRemote.OnClientEvent:Connect(function(catalog)for _,child in scroll:GetChildren()do if child:IsA("Frame")then child:Destroy()end end;local list={};for _,item in catalog.Cosmetics do table.insert(list,item)end;table.sort(list,function(a,b)return a.SortOrder<b.SortOrder end);for _,item in list do card(item)end;for id,product in monetization.Products do local f=Instance.new("Frame");f.Size=UDim2.fromScale(1,.08);f.BackgroundColor3=Color3.fromRGB(65,48,85);f.Parent=scroll;local b=Instance.new("TextButton");b.Size=UDim2.fromScale(1,1);b.Text=product.DisplayName..(product.ProductId==0 and "　[尚未設定]" or "");b.TextScaled=true;b.Parent=f;b.Activated:Connect(function()requestProduct:FireServer(id)end)end;for id,pass in monetization.GamePasses do local f=Instance.new("Frame");f.Size=UDim2.fromScale(1,.08);f.BackgroundColor3=Color3.fromRGB(85,65,35);f.Parent=scroll;local b=Instance.new("TextButton");b.Size=UDim2.fromScale(1,1);b.Text=pass.DisplayName..(pass.GamePassId==0 and "　[尚未設定]" or "");b.TextScaled=true;b.Parent=f;b.Activated:Connect(function()requestPass:FireServer(id)end)end end)
gui:GetPropertyChangedSignal("Enabled"):Connect(function()if gui.Enabled then request:FireServer()end end)
